using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type" in 9.0.
        // Fix: Opt back into the legacy property name for existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id format changed from "EntityType|Key" to just "Key" in 9.0.
        // Fix: Use a value generator or shadow property that preserves the old format.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyIdValueGenerator>();

        // Breaking change 3: HasIndex() now throws for Cosmos in 9.0 (indexes are managed by Cosmos).
        // Fix: Removed the HasIndex call entirely.

        // Breaking change 4: Sync I/O (SaveChanges, ToList) now throws by default in 9.0.
        // Fix: See SyncJob.cs migration to async, or opt back in below.
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // If you cannot migrate to async immediately, re-enable sync I/O:
        // optionsBuilder.UseCosmos("connString", "db", o => o.AllowSynchronousQueryExecution(true));
    }
}

